"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["38029"],{16608(e){e.exports=JSON.parse('{"id":"F062","slug":"expanded-accounting-equation","name":"Expanded Accounting Equation","subject":"Finance Foundations","section":"Accounting Basics","topic":"Double-entry bookkeeping","level":"Intermediate","aliases":["full accounting equation","equity breakdown","accounting equation with revenues and expenses"],"formula":{"latex":"\\\\text{Assets}=\\\\text{Liabilities}+\\\\text{Capital}+RE_{begin}+\\\\text{Revenues}-\\\\text{Expenses}-\\\\text{Dividends}","also":[],"text":"Assets = Liabilities + Contributed capital + Beginning retained earnings + Revenues - Expenses - Dividends"},"symbols":[{"symbol":"Assets","meaning":"Everything the company owns","unit":"money"},{"symbol":"Liabilities","meaning":"Everything the company owes","unit":"money"},{"symbol":"Contributed capital","meaning":"Money the owners put in","unit":"money"},{"symbol":"Beginning retained earnings","meaning":"Profits kept in the business from earlier periods","unit":"money"},{"symbol":"Revenues","meaning":"Income earned this period","unit":"money"},{"symbol":"Expenses","meaning":"Costs this period","unit":"money"},{"symbol":"Dividends","meaning":"Profits paid out to owners this period","unit":"money"}],"when_to_use":"Use it to see why every transaction keeps the accounting equation in balance. Each journal entry changes both sides by the same amount, which is the idea behind double-entry bookkeeping.","worked_example":{"problem":"A company has liabilities of 400, contributed capital of 300 and beginning retained earnings of 200. This year it earned revenues of 500, had expenses of 350 and paid dividends of 50. What are its total assets?","inputs":{"liab":400,"cap":300,"re":200,"rev":500,"exp":350,"div":50},"steps":[{"label":"Equity = capital + beginning RE + revenues - expenses - dividends","working":"300+200+500-exp-50","value":"600.00"},{"label":"Assets = liabilities + equity","working":"400+600","value":"1,000.00"}],"answer":"Total assets are 1,000.00. This equals liabilities of 400 plus equity of 600.00."},"calculator":{"available":false,"reason":"This formula restates the accounting equation in more detail. It explains how entries balance, and the existing accounting equation calculator already covers the arithmetic.","spec_if_wanted_later":{"available":true,"inputs":[{"id":"liab","label":"Liabilities","unit":"money","type":"number","default":400,"hint":""},{"id":"cap","label":"Contributed capital","unit":"money","type":"number","default":300,"hint":""},{"id":"re","label":"Beginning retained earnings","unit":"money","type":"number","default":200,"hint":""},{"id":"rev","label":"Revenues","unit":"money","type":"number","default":500,"hint":""},{"id":"exp","label":"Expenses","unit":"money","type":"number","default":350,"hint":""},{"id":"div","label":"Dividends","unit":"money","type":"number","default":50,"hint":""}],"checks":[],"steps":[{"id":"equity","label":"Equity = capital + beginning RE + revenues - expenses - dividends","expr":"cap+re+rev-exp-div","format":"money"},{"id":"assets","label":"Assets = liabilities + equity","expr":"liab+equity","format":"money"}],"results":["assets"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"equity":600,"assets":1000}}},"finder":{"finds":"How revenues, expenses and dividends fit the accounting equation","needs":"Liabilities, capital, retained earnings, revenues, expenses, dividends"},"related":[{"slug":"accounting-equation","name":"The Accounting Equation"},{"slug":"retained-earnings","name":"Retained Earnings Roll-Forward"},{"slug":"trial-balance","name":"Debits Equal Credits (Trial Balance)"}],"related_ids":["F063","F069","F061"],"group":"Foundations","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Assets</mtext><mo>=</mo><mtext>Liabilities</mtext><mo>+</mo><mtext>Capital</mtext><mo>+</mo><mi>R</mi><msub><mi>E</mi><mrow><mi>b</mi><mi>e</mi><mi>g</mi><mi>i</mi><mi>n</mi></mrow></msub><mo>+</mo><mtext>Revenues</mtext><mo>\u2212</mo><mtext>Expenses</mtext><mo>\u2212</mo><mtext>Dividends</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Assets}=\\\\text{Liabilities}+\\\\text{Capital}+RE_{begin}+\\\\text{Revenues}-\\\\text{Expenses}-\\\\text{Dividends}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"excess-kurtosis","name":"Excess Kurtosis"},"next":{"slug":"expectations-theory","name":"Expectations Theory with a Liquidity Premium"},"lesson":null,"total":522}')}}]);